use mip_codex::{mps,objective_bound::Certifier};
fn main(){let p=std::env::args().nth(1).unwrap();let m=mps::read(&p).unwrap();let exact_zero=m.variables.iter().filter(|v|v.objective==0.&&v.objective_enclosure==Some([0.;2])).count();let nonzero=m.variables.iter().filter(|v|v.objective!=0.).count();let c=Certifier::new(&m);let lower:Vec<_>=m.variables.iter().map(|v|v.lower_enclosure.map(|x|x[0])).collect();let upper:Vec<_>=m.variables.iter().map(|v|v.upper_enclosure.map(|x|x[1])).collect();let bound=c.and_then(|c|c.bound(&lower,&upper,&vec![0.;m.rows.len()]));println!("{}",serde_json::json!({"variables":m.variables.len(),"nonzero_costs":nonzero,"exact_zero_costs":exact_zero,"constant_objective":exact_zero==m.variables.len(),"box_normalized_lower":bound,"offset":m.offset,"offset_enclosure":m.offset_enclosure}));}
